/***************************************************************************************************** 
660. Read N Characters Given Read4 II - Call multiple times

The API: int read4(char *buf) reads 4 characters at a time from a file.

The return value is the actual number of characters read. For example, it returns 3 if there is only 3 characters left in the file.

By using the read4 API, implement the function int read(char *buf, int n) that reads n characters from the file.

Example
Example 1

Input:
"filetestbuffer"
read(6)
read(5)
read(4)
read(3)
read(2)
read(1)
read(10)
Output:
6, buf = "filete"
5, buf = "stbuf"
3, buf = "fer"
0, buf = ""
0, buf = ""
0, buf = ""
0, buf = ""
Example 2

Input:
"abcdef"
read(1)
read(5)
Output:
1, buf = "a"
5, buf = "bcdef"
Notice
The read function may be called multiple times.
 ******************************************************************************************************/

/* The read4 API is defined in the parent class Reader4.
      int read4(char[] buf); */

public class Solution extends Reader4 {

  /**
   * @param buf destination buffer
   * @param n maximum number of characters to read
   * @return the number of characters read
   */
  public int read(char[] buf, int n) {
    // Write your code here
    int i = 0;
    while (i < n && end >= 0) {
      if (start <= end) {
        buf[i] = cache[start++];
        i++;
      } else {
        start = 0;
        end = read4(cache) - 1;
      }
    }

    return i;
  }

  char[] cache = new char[4];
  int start = cache.length; // 从 cache 中哪个位置开始读取
  int end = 0;
}

# The read4 API is already defined for you.
# @param buf, a list of characters
# @return an integer
# def read4(buf):

class Solution(object):
    def __init__(self):
        self.tmp = []
    def read(self, buf, n):
        """
        :type buf: Destination buffer (List[str])
        :type n: Maximum number of characters to read (int)
        :rtype: The number of characters read (int)
        """
        idx = 0
        readcnt = 0
        if self.tmp:
            if n <= len(self.tmp):
                for i in range(n):
                    buf[i+idx] = self.tmp[i]
                del self.tmp[:n]
                return n
            else:
                readcnt += len(self.tmp)
                for c in self.tmp:
                    buf[idx]= c
                    idx+=1
                self.tmp = []
        buff = [None, None, None, None]
        while True:
            nn = read4(buff)
            if nn==0: break
            if readcnt+nn>n:
                for i in range(n-readcnt):
                    buf[idx]=buff[i]
                    idx+=1
                for i in range(n-readcnt, nn):
                    self.tmp.append(buff[i])
                return n
            else:
                readcnt+=nn

                for cc in buff:
                    buf[idx]=cc
                    idx+=1
                if readcnt==n:
                    break
        return readcnt
